using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new NotificationsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
        // Drain the static notification queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);
        var value = jsonResult.Value;
        // Check the anonymous type properties via reflection
        var successProp = value!.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        Assert.NotNull(successProp);
        Assert.NotNull(countProp);
        Assert.True((bool)successProp!.GetValue(value)!);
        Assert.Equal(0, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Arrange - send some notifications via the service accessed by the controller
        var service = new NotificationService();
        service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");
        service.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "Admin");
        service.Dispose();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value;
        Assert.NotNull(value);
        var countProp = value!.GetType().GetProperty("count");
        Assert.NotNull(countProp);
        var count = (int)countProp!.GetValue(value)!;
        Assert.True(count >= 1);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value;
        Assert.NotNull(value);
        var successProp = value!.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp!.GetValue(value)!);
    }
}

