using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "a", "b", "c" };

        // Act
        var result = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, result.Count);
        Assert.Contains("a", result);
        Assert.Contains("b", result);
        Assert.Contains("c", result);
    }

    [Theory]
    [InlineData(10, 3, 4)]   // ceil(10/3) = 4
    [InlineData(9, 3, 3)]    // ceil(9/3) = 3
    [InlineData(1, 10, 1)]   // ceil(1/10) = 1
    [InlineData(0, 10, 0)]   // ceil(0/10) = 0
    [InlineData(11, 5, 3)]   // ceil(11/5) = 3
    public void Constructor_CalculatesTotalPagesCorrectly(int count, int pageSize, int expectedTotalPages)
    {
        // Act
        var result = new PaginatedList<int>(new List<int>(), count, 1, pageSize);

        // Assert
        Assert.Equal(expectedTotalPages, result.TotalPages);
    }

    [Theory]
    [InlineData(1, false)]   // Page 1 has no previous
    [InlineData(2, true)]    // Page 2 has previous
    [InlineData(3, true)]    // Page 3 has previous
    public void HasPreviousPage_ReturnsCorrectValue(int pageIndex, bool expected)
    {
        // Act
        var result = new PaginatedList<int>(new List<int>(), 30, pageIndex, 10);

        // Assert
        Assert.Equal(expected, result.HasPreviousPage);
    }

    [Theory]
    [InlineData(1, 3, true)]   // Page 1 of 3: has next
    [InlineData(2, 3, true)]   // Page 2 of 3: has next
    [InlineData(3, 3, false)]  // Page 3 of 3: no next
    [InlineData(1, 1, false)]  // Page 1 of 1: no next
    public void HasNextPage_ReturnsCorrectValue(int pageIndex, int totalPages, bool expected)
    {
        // pageSize=10, count=totalPages*10 to get the exact TotalPages
        var count = totalPages * 10;
        var result = new PaginatedList<int>(new List<int>(), count, pageIndex, 10);

        Assert.Equal(expected, result.HasNextPage);
    }

    [Fact]
    public void Create_ReturnsCorrectPageOfItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages); // ceil(25/10) = 3
        Assert.Equal(10, result.Count);
        Assert.Equal(11, result[0]); // second page starts at 11
        Assert.Equal(20, result[9]); // second page ends at 20
    }

    [Fact]
    public void Create_FirstPage_SkipsNothingAndTakesPageSize()
    {
        // Arrange
        var source = Enumerable.Range(1, 15).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 5);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(5, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(5, result[4]);
    }

    [Fact]
    public void Create_LastPartialPage_ReturnsRemainingItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 13).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 3, 5);

        // Assert
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(3, result.Count); // only 3 items on last page
        Assert.Equal(11, result[0]);
        Assert.Equal(13, result[2]);
        Assert.False(result.HasNextPage);
        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        // Arrange
        var source = Enumerable.Empty<int>().AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }
}

