using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Additional tests for CoursesController to boost coverage on edit/delete with images.
/// </summary>
public class CoursesControllerAdditionalTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;

    public CoursesControllerAdditionalTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Edit_Post_WithValidImage_UpdatesImagePath()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var editCourse = new Course
        {
            CourseID = course.CourseID,
            Title = course.Title,
            Credits = course.Credits,
            DepartmentID = course.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("newimage.png");
        fileMock.Setup(f => f.Length).Returns(2048);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Edit(editCourse, fileMock.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_FileTooLarge_ReturnsModelError()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var editCourse = new Course
        {
            CourseID = course.CourseID,
            Title = course.Title,
            Credits = course.Credits,
            DepartmentID = course.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("big.jpg");
        fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024);

        var result = _controller.Edit(editCourse, fileMock.Object);

        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_WithExistingImagePath_AttemptsDeletion()
    {
        var course = _context.Courses.First();
        course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old_image.jpg";
        _context.SaveChanges();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

